159	// GetCreatorMaps is a helper function that returns a map of pod replica creators to their single group stats
160	// and a map of pod ids to pod replica creator from a list of pods and it's corresponding VPA.
161	func (f *PodsRestrictionFactoryImpl) GetCreatorMaps(pods []*corev1.Pod, vpa *vpa_types.VerticalPodAutoscaler) (map[podReplicaCreator]singleGroupStats, map[string]podReplicaCreator, error) {
162		livePods := make(map[podReplicaCreator][]*corev1.Pod)
163	
164		for _, pod := range pods {
165			creator, err := getPodReplicaCreator(pod)
166			if err != nil {
167				klog.ErrorS(err, "Failed to obtain replication info for pod", "pod", klog.KObj(pod))
168				continue
169			}
170			if creator == nil {
171				klog.V(0).InfoS("Pod is not managed by any controller", "pod", klog.KObj(pod))
172				continue
173			}
174			livePods[*creator] = append(livePods[*creator], pod)
175		}
176	
177		podToReplicaCreatorMap := make(map[string]podReplicaCreator)
178		creatorToSingleGroupStatsMap := make(map[podReplicaCreator]singleGroupStats)
179	
180		// Use per-VPA minReplicas if present, fall back to the global setting.
181		required := f.minReplicas
182		if vpa.Spec.UpdatePolicy != nil && vpa.Spec.UpdatePolicy.MinReplicas != nil {
183			required = int(*vpa.Spec.UpdatePolicy.MinReplicas)
184			klog.V(3).InfoS("Overriding minReplicas from global to per-VPA value", "globalMinReplicas", f.minReplicas, "vpaMinReplicas", required, "vpa", klog.KObj(vpa))
185		}
186	
187		// if the VPA is using InPlaceOrRecreate update mode and user has opted into skipping disruption, we can skip the replica count check
188		usingInPlaceOrRecreate := vpa_api_util.GetUpdateMode(vpa) == vpa_types.UpdateModeInPlaceOrRecreate
189		usingInPlace := vpa_api_util.GetUpdateMode(vpa) == vpa_types.UpdateModeInPlace
190		skipReplicaCheck := (usingInPlaceOrRecreate || usingInPlace) && f.inPlaceSkipDisruptionBudget
191	
192		for creator, replicas := range livePods {
193			actual := len(replicas)
194	
195			isBelowMinReplicas := false
196			if actual < required {
197				// If checking for unboost, we want to process even if we have fewer replicas than required.
198				hasBoostedPod := slices.ContainsFunc(replicas, func(pod *corev1.Pod) bool {
199					return vpa_api_util.PodHasCPUBoostInProgressAnnotation(pod)
200				})
201				if !hasBoostedPod && !skipReplicaCheck {
202					klog.V(2).InfoS("Too few replicas", "kind", creator.Kind, "object", klog.KRef(creator.Namespace, creator.Name), "livePods", actual, "requiredPods", required, "globalMinReplicas", f.minReplicas)
203					continue
204				}
205				if skipReplicaCheck {
206					klog.V(2).InfoS("in-place-skip-disruption-budget enabled, skipping minReplicas check for in-place update", "kind", creator.Kind, "object", klog.KRef(creator.Namespace, creator.Name), "livePods", actual, "requiredPods", required, "globalMinReplicas", f.minReplicas)
207					isBelowMinReplicas = true
208				}
209			}
210	
211			var configured int
212			if creator.Kind == job {
213				// Job has no replicas configuration, so we will use actual number of live pods as replicas count.
214				configured = actual
215			} else {
216				var err error
217				configured, err = f.getReplicaCount(creator)
218				if err != nil {
219					klog.ErrorS(err, "Failed to obtain replication info", "kind", creator.Kind, "object", klog.KRef(creator.Namespace, creator.Name))
220					continue
221				}
222			}
223	
224			singleGroup := singleGroupStats{}
225			singleGroup.configured = configured
226			singleGroup.evictionTolerance = int(float64(configured) * f.evictionToleranceFraction) // truncated
227			singleGroup.belowMinReplicas = isBelowMinReplicas
228			for _, pod := range replicas {
229				podToReplicaCreatorMap[getPodID(pod)] = creator
230				if pod.Status.Phase == corev1.PodPending {
231					singleGroup.pending = singleGroup.pending + 1
232				}
233				if isInPlaceUpdating(pod) {
234					singleGroup.inPlaceUpdateOngoing = singleGroup.inPlaceUpdateOngoing + 1
235				}
236			}
237			singleGroup.running = len(replicas) - singleGroup.pending
238			creatorToSingleGroupStatsMap[creator] = singleGroup
239		}
240		return creatorToSingleGroupStatsMap, podToReplicaCreatorMap, nil
241	}
