274	func getPodReplicaCreator(pod *corev1.Pod) (*podReplicaCreator, error) {
275		creator := managingControllerRef(pod)
276		if creator == nil {
277			return nil, nil
278		}
279		podReplicaCreator := &podReplicaCreator{
280			Namespace: pod.Namespace,
281			Name:      creator.Name,
282			Kind:      controllerKind(creator.Kind),
283		}
284		return podReplicaCreator, nil
285	}
