287	func managingControllerRef(pod *corev1.Pod) *metav1.OwnerReference {
288		var managingController metav1.OwnerReference
289		for _, ownerReference := range pod.GetOwnerReferences() {
290			if *ownerReference.Controller {
291				managingController = ownerReference
292				break
293			}
294		}
295		return &managingController
296	}
