298	type singleGroupStats struct {
299		configured             int
300		pending                int
301		running                int
302		evictionTolerance      int
303		evicted                int
304		inPlaceUpdateOngoing   int  // number of pods from last loop that are still in-place updating
305		inPlaceUpdateInitiated int  // number of pods from the current loop that have newly requested in-place resize
306		belowMinReplicas       bool // true if this group was allowed through despite being below minReplicas (for in-place only)
307	}
308	
309	// isPodDisruptable checks if all pods are running and eviction tolerance is small, we can
310	// disrupt the current pod.
311	func (s *singleGroupStats) isPodDisruptable() bool {
312		shouldBeAlive := s.configured - s.evictionTolerance
313		actuallyAlive := s.running - (s.evicted + s.inPlaceUpdateInitiated)
314		return actuallyAlive > shouldBeAlive ||
315			(s.configured == s.running && s.evictionTolerance == 0 && s.evicted == 0 && s.inPlaceUpdateInitiated == 0)
316		// we don't want to block pods from being considered for eviction if tolerance is small and some pods are potentially stuck resizing
317	}
318	
319	// isInPlaceUpdating checks whether or not the given pod is currently in the middle of an in-place update
320	func isInPlaceUpdating(podToCheck *corev1.Pod) bool {
321		for _, c := range podToCheck.Status.Conditions {
322			if c.Type == corev1.PodResizePending || c.Type == corev1.PodResizeInProgress {
323				return c.Status == corev1.ConditionTrue
324			}
325		}
326		return false
327	}
328	
329	// getResizeStatus returns the current resize status of a pod based on its conditions.
330	// This is used to determine the appropriate action for pods undergoing in-place updates.
331	func getResizeStatus(pod *corev1.Pod) utils.ResizeStatus {
332		if !isInPlaceUpdating(pod) {
333			return utils.ResizeStatusNone
334		}
335	
336		resizePendingCondition, ok := utils.GetPodCondition(pod, corev1.PodResizePending)
337		if ok {
338			switch resizePendingCondition.Reason {
339			case corev1.PodReasonDeferred:
340				return utils.ResizeStatusDeferred
341			case corev1.PodReasonInfeasible:
342				return utils.ResizeStatusInfeasible
343			default:
344				return utils.ResizeStatusUnknown
345			}
346		}
347	
348		resizeInProgressCondition, ok := utils.GetPodCondition(pod, corev1.PodResizeInProgress)
349		if ok {
350			if resizeInProgressCondition.Reason == "" && resizeInProgressCondition.Message == "" {
351				return utils.ResizeStatusInProgress
352			}
353			if resizeInProgressCondition.Reason == corev1.PodReasonError {
354				return utils.ResizeStatusError
355			}
356		}
357	
358		// Pod is in-place updating but no specific condition found
359		return utils.ResizeStatusUnknown
360	}

